import type { DestinationKind, FilterCategory, Floor } from '../types';

/** Shapes of the files in public/data. Generated by scripts/generate-sample-data.mjs. */

export interface SampleMeta {
  _meta?: { sample: boolean; notice: string };
}

export type SampleCollection<G extends GeoJSON.Geometry, P> = GeoJSON.FeatureCollection<G, P> & SampleMeta;

export interface BuildingProps {
  id: string;
  name: string;
  shortName?: string;
  description?: string;
  categories: FilterCategory[];
  hasIndoorData: boolean;
}

export interface PathProps {
  id: string;
  kind: 'footpath' | 'steps' | 'ramp';
  stepFree: boolean;
  name?: string;
}

export interface EntranceProps {
  id: string;
  buildingId: string;
  name: string;
  stepFree: boolean;
  level: number;
}

export interface PlaceProps {
  id: string;
  name: string;
  kind: DestinationKind;
  categories: FilterCategory[];
  description?: string;
  aliases?: string[];
  buildingId?: string;
}

export interface AreaProps {
  id: string;
  name: string;
  kind: 'water' | 'green';
}

type IndoorNodeKind = 'corridor' | 'stairs' | 'lift' | 'door' | 'entrance';
type IndoorEdgeKind = 'corridor' | 'door' | 'entrance' | 'stairs' | 'lift';

export interface IndoorNode {
  id: string;
  lat: number;
  lng: number;
  level: number;
  kind: IndoorNodeKind;
  name?: string;
}

export interface IndoorEdge {
  from: string;
  to: string;
  kind: IndoorEdgeKind;
  stepFree: boolean;
}

export interface IndoorFeatureProps {
  featureType: 'room' | 'corridor' | 'stairs' | 'lift';
  id: string;
  name?: string;
  kind?: DestinationKind;
  categories?: FilterCategory[];
  buildingId: string;
  floorId: string;
  level: number;
  doorNodeId?: string;
  nodeId?: string;
}

export interface IndoorData extends SampleMeta {
  buildingId: string;
  floors: Floor[];
  nodes: IndoorNode[];
  edges: IndoorEdge[];
  features: GeoJSON.FeatureCollection<GeoJSON.Polygon, IndoorFeatureProps>;
}

export const SAMPLE_FILES = {
  buildings: 'campus/buildings.geojson',
  paths: 'campus/paths.geojson',
  entrances: 'campus/entrances.geojson',
  places: 'campus/places.geojson',
  areas: 'campus/areas.geojson',
  indoor: (buildingId: string) => `indoor/${buildingId}.json`,
} as const;
